import json

def keep_only_horizontal_lines(row, col):
    # Keep 1s only at row 0 cols 17-21 or row 6 cols 0-4
    if (row == 0 and 17 <= col <= 21) or (row == 6 and 0 <= col <= 4):
        return 1
    # Remove 3s: turn them into 9
    if row == 3 and col in [0, 3]:
        return 9
    if row == 4 and col in [1, 2]:
        return 9
    if col == 2 and row == 2:
        return 9
    if col == 4 and row == 4:
        return 9
    # Pass through
    return row

